import { EmailContentTypes } from '../../../enums/Email/EmailContentTypes.js';
import { EmailParams } from './EmailParams.js';
import '../../MessageParams.js';
import '../../../enums/Channels.js';
import '../../../enums/MessageTypes.js';
import './EmailSettings.js';
import '../../../enums/Email/EmailImportance.js';
import '../../../enums/Email/EmailPriority.js';
import '../../../enums/Email/EmailSensitivity.js';
import './EmailRecipient.js';

type TextContentEmailParams = {
    /**
     * The type for the content object. Must be text.
     */
    type: EmailContentTypes.TEXT;
    /**
     * The text content to display in the message.
     */
    text: string;
};
type HTMLContentEmailParams = {
    /**
     * The type for the content object. Must be html.
     */
    type: EmailContentTypes.HTML;
    /**
     * The HTML content to display in the message.
     */
    body: string;
};
/**
 * Represents the parameters for a HTML Email Message
 *
 * @group Email
 * @category Parameters
 */
type ContentEmailParams = {
    /**
     * The content and structure of the HTML email message.
     */
    content: Array<TextContentEmailParams | HTMLContentEmailParams>;
} & EmailParams;

export type { ContentEmailParams, HTMLContentEmailParams, TextContentEmailParams };
